    34→type BlockValidator struct {
    35→	config *params.ChainConfig // Chain configuration options
    36→	bc     *BlockChain         // Canonical block chain
    37→}
    38→
    39→// NewBlockValidator returns a new block validator which is safe for re-use
    40→func NewBlockValidator(config *params.ChainConfig, blockchain *BlockChain) *BlockValidator {
    41→	validator := &BlockValidator{
    42→		config: config,
    43→		bc:     blockchain,
    44→	}
    45→	return validator
    46→}
    47→
    48→// ValidateBody validates the given block's uncles and verifies the block
    49→// header's transaction and uncle roots. The headers are assumed to be already
    50→// validated at this point.
    51→func (v *BlockValidator) ValidateBody(block *types.Block) error {
    52→	// check EIP 7934 RLP-encoded block size cap
    53→	if v.config.IsOsaka(block.Number(), block.Time()) && block.Size() > params.MaxBlockSize {
    54→		return ErrBlockOversized
    55→	}
    56→	// Check whether the block is already imported.
    57→	if v.bc.HasBlockAndState(block.Hash(), block.NumberU64()) {
    58→		return ErrKnownBlock
    59→	}
    60→
    61→	// Header validity is known at this point. Here we verify that uncles, transactions
    62→	// and withdrawals given in the block body match the header.
    63→	header := block.Header()
    64→	if err := v.bc.engine.VerifyUncles(v.bc, block); err != nil {
    65→		return err
    66→	}
    67→	if hash := types.CalcUncleHash(block.Uncles()); hash != header.UncleHash {
    68→		return fmt.Errorf("uncle root hash mismatch (header value %x, calculated %x)", header.UncleHash, hash)
    69→	}
    70→	if hash := types.DeriveSha(block.Transactions(), trie.NewStackTrie(nil)); hash != header.TxHash {
    71→		return fmt.Errorf("transaction root hash mismatch (header value %x, calculated %x)", header.TxHash, hash)
    72→	}
    73→
    74→	// Withdrawals are present after the Shanghai fork.
    75→	if header.WithdrawalsHash != nil {
    76→		// Withdrawals list must be present in body after Shanghai.
    77→		if block.Withdrawals() == nil {
    78→			return errors.New("missing withdrawals in block body")
    79→		}
    80→		if hash := types.DeriveSha(block.Withdrawals(), trie.NewStackTrie(nil)); hash != *header.WithdrawalsHash {
    81→			return fmt.Errorf("withdrawals root hash mismatch (header value %x, calculated %x)", *header.WithdrawalsHash, hash)
    82→		}
    83→	} else if block.Withdrawals() != nil {
    84→		// Withdrawals are not allowed prior to Shanghai fork
    85→		return errors.New("withdrawals present in block body")
    86→	}
    87→
    88→	// Blob transactions may be present after the Cancun fork.
    89→	var blobs int
    90→	for i, tx := range block.Transactions() {
    91→		// Count the number of blobs to validate against the header's blobGasUsed
    92→		blobs += len(tx.BlobHashes())
    93→
    94→		// If the tx is a blob tx, it must NOT have a sidecar attached to be valid in a block.
    95→		if tx.BlobTxSidecar() != nil {
    96→			return fmt.Errorf("unexpected blob sidecar in transaction at index %d", i)
    97→		}
    98→
    99→		// The individual checks for blob validity (version-check + not empty)
   100→		// happens in state transition.
   101→	}
   102→
   103→	// Check blob gas usage.
   104→	if header.BlobGasUsed != nil {
   105→		if want := *header.BlobGasUsed / params.BlobTxBlobGasPerBlob; uint64(blobs) != want { // div because the header is surely good vs the body might be bloated
   106→			return fmt.Errorf("blob gas used mismatch (header %v, calculated %v)", *header.BlobGasUsed, blobs*params.BlobTxBlobGasPerBlob)
   107→		}
   108→	} else {
   109→		if blobs > 0 {
   110→			return errors.New("data blobs present in block body")
   111→		}
   112→	}
   113→
   114→	// Ancestor block must be known.
   115→	if !v.bc.HasBlockAndState(block.ParentHash(), block.NumberU64()-1) {
   116→		if !v.bc.HasBlock(block.ParentHash(), block.NumberU64()-1) {
   117→			return consensus.ErrUnknownAncestor
   118→		}
   119→		return consensus.ErrPrunedAncestor
   120→	}
   121→	return nil
   122→}
