   124→// ValidateState validates the various changes that happen after a state transition,
   125→// such as amount of used gas, the receipt roots and the state root itself.
   126→func (v *BlockValidator) ValidateState(block *types.Block, statedb *state.StateDB, res *ProcessResult, stateless bool) error {
   127→	if res == nil {
   128→		return errors.New("nil ProcessResult value")
   129→	}
   130→	header := block.Header()
   131→	if block.GasUsed() != res.GasUsed {
   132→		return fmt.Errorf("invalid gas used (remote: %d local: %d)", block.GasUsed(), res.GasUsed)
   133→	}
   134→	// Validate the received block's bloom with the one derived from the generated receipts.
   135→	// For valid blocks this should always validate to true.
   136→	//
   137→	// Receipts must go through MakeReceipt to calculate the receipt's bloom
   138→	// already. Merge the receipt's bloom together instead of recalculating
   139→	// everything.
   140→	rbloom := types.MergeBloom(res.Receipts)
   141→	if rbloom != header.Bloom {
   142→		return fmt.Errorf("invalid bloom (remote: %x  local: %x)", header.Bloom, rbloom)
   143→	}
   144→	// In stateless mode, return early because the receipt and state root are not
   145→	// provided through the witness, rather the cross validator needs to return it.
   146→	if stateless {
   147→		return nil
   148→	}
   149→	// The receipt Trie's root (R = (Tr [[H1, R1], ... [Hn, Rn]]))
   150→	receiptSha := types.DeriveSha(res.Receipts, trie.NewStackTrie(nil))
   151→	if receiptSha != header.ReceiptHash {
   152→		return fmt.Errorf("invalid receipt root hash (remote: %x local: %x)", header.ReceiptHash, receiptSha)
   153→	}
   154→	// Validate the parsed requests match the expected header value.
   155→	if header.RequestsHash != nil {
   156→		reqhash := types.CalcRequestsHash(res.Requests)
   157→		if reqhash != *header.RequestsHash {
   158→			return fmt.Errorf("invalid requests hash (remote: %x local: %x)", *header.RequestsHash, reqhash)
   159→		}
   160→	} else if res.Requests != nil {
   161→		return errors.New("block has requests before prague fork")
   162→	}
   163→	// Validate the state root against the received state root and throw
   164→	// an error if they don't match.
   165→	if root := statedb.IntermediateRoot(v.config.IsEIP158(header.Number)); header.Root != root {
   166→		return fmt.Errorf("invalid merkle root (remote: %x local: %x) dberr: %w", header.Root, root, statedb.Error())
   167→	}
   168→	return nil
   169→}
