   171→// CalcGasLimit computes the gas limit of the next block after parent. It aims
   172→// to keep the baseline gas close to the provided target, and increase it towards
   173→// the target if the baseline gas is lower.
   174→func CalcGasLimit(parentGasLimit, desiredLimit uint64) uint64 {
   175→	delta := parentGasLimit/params.GasLimitBoundDivisor - 1
   176→	limit := parentGasLimit
   177→	if desiredLimit < params.MinGasLimit {
   178→		desiredLimit = params.MinGasLimit
   179→	}
   180→	// If we're outside our allowed gas range, we try to hone towards them
   181→	if limit < desiredLimit {
   182→		limit = parentGasLimit + delta
   183→		if limit > desiredLimit {
   184→			limit = desiredLimit
   185→		}
   186→		return limit
   187→	}
   188→	if limit > desiredLimit {
   189→		limit = parentGasLimit - delta
   190→		if limit < desiredLimit {
   191→			limit = desiredLimit
   192→		}
   193→	}
   194→	return limit
   195→}
